    def __init__(self):
        super().__init__()
        self._urls = []

    @asyncio.coroutine
    def resolve(self, request):
        path = request.path
        method = request.method
        allowed_methods = set()
        for entry in self._urls:
            match = entry.regex.match(path)
            if match is None:
                continue
            if entry.method != method:
                allowed_methods.add(entry.method)
            else:
                break
        else:
            if allowed_methods:
                allow = ', '.join(sorted(allowed_methods))
                # add log
                raise HTTPMethodNotAllowed(request, headers={'ALLOW', allow})
            else:
                # add log
                raise HTTPNotFound(request)

        matchdict = match.groupdict()
        return UrlMappingMatchInfo(matchdict, entry)

