        """Send pong message."""
        self._send_frame(b'', OPCODE_PONG)

    def ping(self):
        """Send pong message."""
        self._send_frame(b'', OPCODE_PING)

    def send(self, message, binary=False):
        """Send a frame over the websocket with message as its payload."""
        if isinstance(message, str):
